from packaging.version import parse
from packaging.version import Version
for s in ['0.10.0','0.6','builtin','4.3.0+/26c','1.0b1','1.0.dev0','1.0+local','1.0+abc/def']:
    try:
        v=parse(s)
        print(s,'->',v,type(v))
    except Exception as e:
        print(s,'->',type(e).__name__,e)
